    def _build_selfcheck(self) -> Dict[str, Any]:
        report = dict(super()._build_selfcheck())
        checks = list(report.get("checks") or [])
        source_count = int(self._offline_source_summary()["total"])
        try:
            client, api = self._get_guangya_runtime()
            native_ok = bool(client and api and callable(getattr(client, "_request", None)))
        except Exception:
            native_ok = False
        checks.append({
            "key": "native_offline",
            "label": "光鸭原生云添加",
            "ok": native_ok or source_count == 0,
            "detail": (
                "cloudcollection 可用，Magnet/ED2K 不经过 MoviePilot 下载器"
                if native_ok
                else ("尚未添加 Magnet/ED2K 来源" if source_count == 0 else "光鸭客户端不可用，云添加来源将等待恢复")
            ),
            "critical": bool(source_count),
        })
        report["checks"] = checks
        report["healthy"] = not any(item.get("critical") and not item.get("ok") for item in checks)
        report["offline_sources"] = self._offline_source_summary()
        report["build"] = self.build_id
        return report

    def _writeback_offline_candidate_diag_v209(
        self,
        source: Dict[str, Any],
        *,
        state: str,
        reason_code: str,
        stage: str,
        message: str = "",
    ) -> None:
        """Append terminal/pending diag to Resource Trace using action-carried ids (idempotent)."""
        if not isinstance(source, dict):
            return
        resource_trace = str(source.get("resource_trace_id") or "").strip()
        candidate_trace = str(source.get("candidate_trace_id") or "").strip()
        if not resource_trace and not candidate_trace:
            return
        # First terminal wins.
        terminal_key = f"diag_terminal::{candidate_trace or resource_trace}"
        if state in {"SUCCESS", "FAILED_FINAL", "FAILED_RETRYABLE", "SKIPPED", "SKIPPED_COMPLETE"}:
            if bool(source.get(terminal_key)):
                return
            try:
                self._update_source(str(source.get("id") or ""), **{terminal_key: True})
            except Exception:
                pass
        try:
            from .transfer_diag_v209 import make_diag
        except Exception:
            return
        row = make_diag(
            state=state,
            reason_code=reason_code,
            stage=stage,
            source=str(source.get("type") or "magnet"),
            message=str(message or "")[:360],
            resource_trace_id=resource_trace,
            candidate_trace_id=candidate_trace,
            subscription_run_id=str(source.get("subscription_run_id") or ""),
            sid=source.get("subscribe_id"),
            evidence={
                "source_id": str(source.get("id") or ""),
                "task_id": str(source.get("task_id") or ""),
                "identity": str(source.get("diag_identity") or source.get("identity") or "")[:120],
                "message_id": str(source.get("message_id") or ""),
            },
        )
        note = getattr(self, "_note_candidate_diag_v209", None)
        if callable(note):
            try:
                note(row)
                return
            except Exception:
                pass
        # Worker may run outside subscription TLS — write resource trace directly.
        tracer = getattr(self, "_resource_trace_v209", None)
        if callable(tracer) and resource_trace:
            try:
                tracer(
                    entry={
                        "resource_trace_id": resource_trace,
                        "message_id": str(source.get("message_id") or "-"),
                        "source_url": str(source.get("source_label") or ""),
                        "title": str(source.get("label") or ""),
                    },
                    state=f"{stage}/{state}",
                    reason=f"{reason_code}|{candidate_trace}|{str(message)[:120]}",
                    matched_sid=source.get("subscribe_id"),
                )
            except Exception:
                pass


__all__ = ["GuangYaMultiSourceMixin"]

offline_safety_v180:
"""v1.8.0 光鸭原生云添加安全收口。

该层只修正任务恢复和对外展示，不改变 multisource_v180 的业务入口：
- 有 taskId 的 queued/submitted/waiting 永远轮询，不重复 create_task；
- 已提交任务的临时轮询网络错误不会把任务误判为永久失败；
- 来源列表不返回 Magnet tracker 等原始 URI，避免把可能含私有参数的链接暴露到状态接口。
"""

from __future__ import annotations

from typing import Any, Dict

from .source_types_v180 import SOURCE_INFLIGHT_STATES


class GuangYaOfflineSafetyMixin:
    """必须放在 GuangYaMultiSourceMixin 之前。"""

    def _submit_offline_source(self, source_id: str) -> Dict[str, Any]:
        source = dict(self._source_store()["items"].get(str(source_id or "")) or {})
        task_id = str(source.get("task_id") or "").strip()
        state = str(source.get("state") or "new")
        if task_id:
            if state == "completed":
                return {"success": True, "message": "来源已完成", "data": source}
            if state in {"retry", "failed"}:
                return self._retry_offline_task(source)
            # 只要服务端任务已经存在，不论旧版本落下什么中间 state，都只能查询既有任务。
            return self._poll_offline_source(source)
        return super()._submit_offline_source(source_id)

    def _poll_offline_source(self, source: Dict[str, Any]) -> Dict[str, Any]:
        before_attempts = int(source.get("attempts") or 0)
        result = super()._poll_offline_source(source)
        data = result.get("data") if isinstance(result, dict) else None
        if not isinstance(data, dict):
            return result

        task_status = data.get("task_status")
        try:
            task_status_code = int(task_status if task_status is not None else -1)
        except (TypeError, ValueError):
            task_status_code = -1

        # status=5 是光鸭明确返回的部分完成/失败，允许进入 retry/failed。
        # 其它失败若已有 taskId，则属于“查询暂不可用”，必须保留任务等待下轮，不得重新提交。
        if (
            str(source.get("task_id") or "").strip()
            and not bool(result.get("success"))
            and task_status_code != 5
        ):
            updated = self._update_source(
                str(source.get("id") or ""),
                state="waiting",
                attempts=before_attempts,
                next_retry_at=0,
                last_error=str(result.get("message") or data.get("last_error") or "任务状态查询暂不可用")[:500],
            ) or data
            return {
                "success": False,
                "message": str(result.get("message") or "任务状态查询暂不可用，已保留 taskId 等待恢复"),
                "data": updated,
            }
        return result

    @staticmethod
    def _source_public_view(source: Dict[str, Any]) -> Dict[str, Any]:
        row = dict(source or {})
        raw_uri = str(row.pop("uri", "") or "")
        source_type = str(row.get("type") or "")
        identity = str(row.get("identity") or "")
        name = str(row.get("name") or row.get("resolved_name") or "")[:120]
        size = int(row.get("size") or 0)
        if source_type == "magnet":
            row["uri_preview"] = f"magnet:?xt=urn:btih:{identity}"
        elif source_type == "ed2k":
            row["uri_preview"] = f"ed2k://|file|{name}|{size}|{identity}|/"
        else:
            row["uri_preview"] = raw_uri[:120]
        return row

    def api_source_list(self, subscribe_id: int = 0) -> Dict[str, Any]:
        sid = int(subscribe_id or 0)
        rows = []
        for source in self._source_store()["items"].values():
            if not isinstance(source, dict):
                continue
            if sid and int(source.get("subscribe_id") or 0) != sid:
                continue
            rows.append(self._source_public_view(source))
        rows.sort(key=lambda row: str(row.get("updated_at") or ""), reverse=True)
        return {"success": True, "count": len(rows), "data": rows[:100]}


__all__ = ["GuangYaOfflineSafetyMixin"]

page_auth_v172:
"""光鸭转存助手页面 API 与页面故障隔离兼容层。

MoviePilot V3 插件页面使用当前登录会话的 Bearer 鉴权。页面事件只传业务参数，
不把 API_TOKEN 作为 token/apikey 注入按钮参数。

状态页的“立即检查缺集/复查待落盘”不能在 HTTP 请求线程里同步跑完整频道读取、
分享解析和转存流程，否则前端会在网络稍慢时提示“服务无响应”。本层把这两类操作
送入插件已经存在的可靠后台合并队列，并立即返回标准三段式 Response envelope；
其余状态页操作也统一收口为严格的 success/message/data 三字段响应。

v1.10.2 追加页面故障隔离：新版控制台会同时读取自检、资源计划、频道缓存、Provider
配置和迅雷运行态。升级后任意一份旧缓存形态异常，或者任意运行时探针抛错，都不应让
MoviePilot 整个插件页返回“数据加载失败”。本层在不改变转存业务逻辑的前提下，对这些
只读页面数据做 fail-soft 包装：失败模块降级显示，控制台本身继续可用，并把详细异常写入
插件日志供排障。
"""

from __future__ import annotations

import functools
from typing import Any, Dict, List


_STATUS_ACTION_PATHS = {
    "/check_missing",
    "/recheck_pending",
    "/cancel_pending",
    "/reset_state",
    "/release_native",
    "/daily_summary",
    "/clear_plugin_logs",
}
_ASYNC_STATUS_PATHS = {
    "/check_missing": "状态页立即检查缺集",
    "/recheck_pending": "状态页复查待落盘",
}


def _response_envelope(result: Any, default_message: str = "操作完成") -> Dict[str, Any]:
    """把旧版插件 API 返回值规范成 MoviePilot V3 严格三段式响应。"""
    if isinstance(result, dict):
        success = bool(result.get("success", True))
        message = str(result.get("message") or (default_message if success else "操作失败"))
        data = {
            key: value
            for key, value in result.items()
            if key not in {"success", "message"}
        }
        return {
            "success": success,
            "message": message,
            "data": data or None,
        }
    return {
        "success": True,
        "message": default_message,
        "data": result,
    }


def _subscription_id(args: tuple, kwargs: dict) -> int:
    """从 FastAPI 绑定参数中稳健取得 subscribe_id。"""
    value = kwargs.get("subscribe_id")
    if value in (None, "") and args:
        value = args[0]
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _queue_status_action(path: str, endpoint: Any, *args, **kwargs) -> Dict[str, Any]:
    """校验状态页耗时操作并提交现有可靠后台队列，HTTP 立即返回。"""
    plugin = getattr(endpoint, "__self__", None)
    if plugin is None:
        return {
            "success": False,
            "message": "插件运行实例不可用，请刷新页面后重试",
            "data": None,
        }

    sid = _subscription_id(args, kwargs)
    subscribe = plugin._find_subscription(sid) if sid else None
    if not sid or subscribe is None:
        return {
            "success": False,
            "message": "订阅不存在",
            "data": {"subscribe_id": sid} if sid else None,
        }

    selected = {
        int(value)
        for value in (getattr(plugin, "_selected_subscriptions", None) or [])
        if str(value).isdigit() and int(value) > 0
    }
    if sid not in selected:
        return {
            "success": False,
            "message": "该订阅当前不是光鸭固定转存路线",
            "data": {"subscribe_id": sid},
        }

    runtime_check = getattr(plugin, "_runtime_is_current", None)
    if callable(runtime_check) and not runtime_check():
        return {
            "success": False,
            "message": "插件已热更新，请刷新当前页面后重试",
            "data": {"subscribe_id": sid},
        }

    # “立即检查缺集”保留原人工门禁：已有待落盘任务时不能强制重放旧消息。
    if path == "/check_missing":
        manual_guard = getattr(plugin, "_manual_transfer_guard", None)
        if callable(manual_guard):
            guard = manual_guard(subscribe)
            if guard:
                return _response_envelope(guard, default_message="检查被安全门禁阻止")

    trigger = _ASYNC_STATUS_PATHS[path]
    try:
        plugin._queue_async_route_check([sid], trigger=trigger)
        record_health = getattr(plugin, "_record_route_health", None)
        if callable(record_health):
            record_health(
                last_page_action_queued=trigger,
                last_page_action_id=sid,
                last_page_action_at=plugin._now_text(),
            )
        plugin._plugin_log(
            "INFO",
            "【光鸭转存助手】【页面操作】%s #%s %s 已进入后台队列，HTTP 请求立即返回",
            trigger,
            sid,
            getattr(subscribe, "name", ""),
        )
    except Exception as err:
        plugin._plugin_log(
            "EXCEPTION",
            "【光鸭转存助手】【页面操作】%s #%s 入队失败：%s",
            trigger,
            sid,
            err,
        )
        return {
            "success": False,
            "message": f"后台任务提交失败：{err}",
            "data": {"subscribe_id": sid},
        }

    return {
        "success": True,
        "message": "已进入后台检查队列，请稍后查看状态卡片或插件日志",
        "data": {
            "subscribe_id": sid,
            "queued": True,
            "action": path.lstrip("/"),
        },
    }


def _wrap_status_endpoint(path: str, endpoint: Any) -> Any:
    """保持原 FastAPI 签名，同时统一状态页操作响应。"""
    if path in _ASYNC_STATUS_PATHS:
        @functools.wraps(endpoint)
        def queued_endpoint(*args, **kwargs):
            return _queue_status_action(path, endpoint, *args, **kwargs)

        return queued_endpoint

    @functools.wraps(endpoint)
    def response_endpoint(*args, **kwargs):
        return _response_envelope(endpoint(*args, **kwargs))

    return response_endpoint


def force_bear_auth(routes: Any) -> List[Dict[str, Any]]:
    """统一 Bearer 鉴权，并给状态页按钮安装非阻塞/标准响应适配器。"""
    result: List[Dict[str, Any]] = []
    for route in list(routes or []):
        if not isinstance(route, dict):
            continue
        item = dict(route)
        item["auth"] = "bear"
        path = str(item.get("path") or "")
        endpoint = item.get("endpoint")
        if path in _STATUS_ACTION_PATHS and callable(endpoint):
            item["endpoint"] = _wrap_status_endpoint(path, endpoint)
        result.append(item)
    return result


def strip_page_api_secrets(node: Any) -> None:
    """递归移除状态页按钮中的 token/apikey，仅保留业务参数。"""
    if isinstance(node, dict):
        events = node.get("events")
        if isinstance(events, dict):
            click = events.get("click")
            if isinstance(click, dict) and str(click.get("api") or "").startswith(
                "plugin/GuangYaTransferAssistant/"
            ):
                params = click.get("params")
                if isinstance(params, dict):
                    params.pop("token", None)
                    params.pop("apikey", None)
        for value in node.values():
            strip_page_api_secrets(value)
    elif isinstance(node, list):
        for value in node:
            strip_page_api_secrets(value)


# ---------------------------------------------------------------------------
# v1.10.2 页面数据故障隔离
# ---------------------------------------------------------------------------

def _page_log_error(plugin: Any, stage: str, err: Exception) -> None:
    """页面降级只记录异常，不让记录异常本身再次影响页面返回。"""
    try:
        log = getattr(plugin, "_plugin_log", None)
        if callable(log):
            log(
                "EXCEPTION",
                "【光鸭转存助手】【页面降级】%s 读取失败，已隔离该模块：%s",
                stage,
                err,
            )
    except Exception:
        pass


def _page_mark_error(plugin: Any, stage: str, err: Exception) -> None:
    """记录当前一次页面构建的降级模块名称，前端只展示模块名而不泄露异常原文。"""
    _page_log_error(plugin, stage, err)
    try:
        rows = getattr(plugin, "_page_resilience_errors_v1102", None)
        if not isinstance(rows, list):
            rows = []
            setattr(plugin, "_page_resilience_errors_v1102", rows)
        if stage not in rows:
            rows.append(stage)
    except Exception:
        pass


def _fallback_overview(plugin: Any, stage: str = "状态汇总") -> Dict[str, Any]:
    """提供新控制台所需的完整最小字段，避免二次 KeyError。"""
    try:
        selected = len(list(getattr(plugin, "_selected_subscriptions", None) or []))
    except Exception:
        selected = 0
    return {
        "overall": "warning",
        "healthy": False,
        "attention_count": 0,
        "selected": selected,
        "channel_count": 0,
        "channel_updated": "-",
        "channel_errors": 0,
        "sources": {
            "total": 0,
            "magnet": 0,
            "ed2k": 0,
            "pending": 0,
            "running": 0,
            "completed": 0,
            "failed": 0,
            "review": 0,
        },
        "critical_checks": [],
        "warning_checks": [{
            "key": "page_data_degraded",
            "label": "页面状态数据已降级",
            "detail": f"{stage}暂时不可用，后台转存任务不会因此停止",
            "critical": False,
            "ok": False,
        }],
        "attention_sources": [],
        "failed_transfer_rows": [],
        "active_sources": [],
        "active_transfer_rows": [],
        "waiting_resource_count": 0,
        "resource_plan_count": 0,
        "version": str(getattr(plugin, "plugin_version", "")),
