    def _unified_provider_search(self, keyword: str) -> Dict[str, Any]:
        keyword = str(keyword or "").strip()
        if not keyword:
            return {"success": False, "keyword": "", "message": "搜索关键词不能为空", "data": [], "xunlei": [], "states": []}

        candidates: List[Dict[str, Any]] = []
